SELECT CASE WHEN s.risk_reward_ratio < 0.75 THEN 'a<0.75' WHEN s.risk_reward_ratio < 1 THEN 'b0.75-1' WHEN s.risk_reward_ratio < 1.5 THEN 'c1-1.5' ELSE 'd>=1.5' END AS rr_band, p.status, COUNT(*) AS n, SUM(p.realized_pnl < 0) AS losses, ROUND(SUM(p.realized_pnl), 6) AS pnl_sum, ROUND(AVG(s.atr_percent), 4) AS avg_atr_pct, ROUND(AVG(m.entry_quality_score), 1) AS avg_eq, ROUND(AVG(m.profit_lock_progress_percent), 2) AS avg_progress_pct FROM paper_position p JOIN trade_signal s ON s.id = p.signal_id LEFT JOIN wallet_managed_position m ON m.entry_signal_id = p.signal_id WHERE p.status IN ('CLOSED','STOPPED') AND p.closed_at IS NOT NULL GROUP BY rr_band, p.status ORDER BY rr_band, p.status